float glitter(vec2 uv, int seed_offset)
{
    // tile size (we'll draw a bunch of disks inside every tile)
    const float TILE_SIZE = .08;

    // number of disks in every tile
    const int N_DISKS = 40;

    // radius of the disks
    // should be a lot smaller than (TILE_SIZE / 2)
    const float DISK_RADIUS = .003;
    const float DISK_RADIUS_SQ = DISK_RADIUS * DISK_RADIUS;

    // 2D index of the current tile
    ivec2 itile = ivec2(floor(uv / TILE_SIZE));

    // bottom left and top right coordinates of the tile
    vec2 tile_bl = vec2(itile) * TILE_SIZE;
    vec2 tile_tr = tile_bl + TILE_SIZE;

    // re-seed PRNG with the tile index
    prng_init(uvec2(itile + 115249 * seed_offset));

    // draw a bunch of disks inside the current tile
    float v = 0.;
    for (int i = 0; i < N_DISKS; i++)
    {
        vec2 center = vec2(
            remap(
                random(),
                0.,
                1.,
                tile_bl.x + DISK_RADIUS,
                tile_tr.x - DISK_RADIUS
            ),
            remap(
                random(),
                0.,
                1.,
                tile_bl.y + DISK_RADIUS,
                tile_tr.y - DISK_RADIUS
            )
        );

        float brightness = pow(random(), 7.);

        if (dist_sq(uv, center) < DISK_RADIUS_SQ)
        {
            v = max(v, brightness);
        }
    }
    return v;
}

vec3 render(vec2 coord)
{
    // 2D world-space UV coordinates
    vec2 orig_uv = screen_to_uv(coord, iResolution.xy);
    vec2 uv = orig_uv;

    // translate UV
    uv += vec2(.01 * iTime, -.02 * iTime);

    // distort UV to create wobbly effect
    uv += .11 * vec2(
        perlin(1.4 * uv + 20. + .12 * iTime),
        perlin(1.4 * uv - 20. + .06 * iTime)
    );

    // sample noise
    float v = smoothstep(-.45, .38, perlin_fractal(1.6 * uv, 2, -.15, 2.));
    v = clamp(v, 0., 1.);

    // modulate v
    v = fract(v - .03 * iTime);

    // choose palette index
    int palette_idx = int(iTime / 4.) % N_PALETTES;
    int first_color_idx = palette_idx * N_COLORS_IN_PALETTE;

    // put v into a colormap (gradient)
    vec3 col = PALETTES[first_color_idx];
    for (int i = 0; i < N_COLORS_IN_PALETTE - 1; i++)
    {
        col = mix(
            col,
            PALETTES[first_color_idx + i + 1],
            step(
                (float(i) + .5) / float(N_COLORS_IN_PALETTE - 1),
                v
            )
        );
    }

    // add grain
    float col_lum = dot(col, vec3(.3, .5, .2));
    col = mix(
        col,
        vec3(1),
        glitter(orig_uv, int(iTime / .3)) * remap(col_lum, 0., 1., .08, .04)
    );

    return col;
}

void mainImage(out vec4 frag_col, in vec2 frag_coord)
{
    // render with grid multisampling
    vec3 col = vec3(0);
    for (int y = -1; y <= 1; y++)
    {
        for (int x = -1; x <= 1; x++)
        {
            col += render(frag_coord + .35 * vec2(x, y));
        }
    }
    col /= 9.;

    // output
    col = pow(col, vec3(1. / 2.2));
    frag_col = vec4(col, 1);
}

