// https://www.shadertoy.com/view/Ml3Gz8
float smoothmin(float a, float b, float k) {
    float h = clamp(0.5 + 0.5*(a-b)/k, 0.0, 1.0);
    return mix(a, b, h) - k*h*(1.0-h);
}

vec2 perpendicular(vec2 dir)
{
    return vec2(-dir.y, dir.x);
}

float dist_sq(vec2 a, vec2 b)
{
    vec2 temp = a - b;
    return dot(temp, temp);
}

float dist_along_line(vec2 p, vec2 line_start, vec2 line_end)
{
    vec2 dir = line_end - line_start;

    // normalize
    float len_sqr = dot(dir, dir);
    if (len_sqr < .0001)
        return 1e9;
    dir /= sqrt(len_sqr);

    return dot(
        dir,
        p - line_start
    );
}

float relative_dist_along_line(vec2 p, vec2 line_start, vec2 line_end)
{
    vec2 dir = line_end - line_start;
    return dot(
        dir,
        p - line_start
    );
}

vec2 screen_to_uv(vec2 coord, vec2 res)
{
    return 2. * (coord - .5 * res) / min(res.x, res.y);
}

float bilinear(
    float val_bl,
    float val_tl,
    float val_tr,
    float val_br,
    vec2 offs
)
{
    return mix(
        mix(val_bl, val_br, offs.x),
        mix(val_tl, val_tr, offs.x),
        offs.y
    );
}

float perlin(vec2 coord)
{
    // Cell indices
    ivec2 icell = ivec2(floor(coord));

    // Cell corners
    vec2 cell_bl = vec2(icell);
    vec2 cell_tl = cell_bl + vec2(0, 1);
    vec2 cell_tr = cell_bl + vec2(1, 1);
    vec2 cell_br = cell_bl + vec2(1, 0);

    // Cell offset in [0, 1) range (vector pointing from the bottom
    // left corner to coord)
    vec2 cell_offs = coord - cell_bl;

    // Generate a random unit vector at each cell corner and take
    // the distance that coord has traveled along that line

    prng_init(uvec2(icell));
    vec2 grad_bl = random_unit_vec2();

    prng_init(uvec2(icell) + uvec2(0, 1));
    vec2 grad_tl = random_unit_vec2();

    prng_init(uvec2(icell) + uvec2(1, 1));
    vec2 grad_tr = random_unit_vec2();

    prng_init(uvec2(icell) + uvec2(1, 0));
    vec2 grad_br = random_unit_vec2();

    float dist_bl = relative_dist_along_line(coord, cell_bl, cell_bl + grad_bl);
    float dist_tl = relative_dist_along_line(coord, cell_tl, cell_tl + grad_tl);
    float dist_tr = relative_dist_along_line(coord, cell_tr, cell_tr + grad_tr);
    float dist_br = relative_dist_along_line(coord, cell_br, cell_br + grad_br);

    // Smoothstep the cell offset vector
    cell_offs = smoothstep(0., 1., cell_offs);

    // Bilinear interpolation between the four distances
    float val = bilinear(
        dist_bl,
        dist_tl,
        dist_tr,
        dist_br,
        cell_offs
    );

    return val;
}

// Random offset for a sample point inside a cell
vec2 cell_corner_offs(ivec2 icell)
{
    prng_init(uvec2(icell));
    return 1. *  (vec2(random(), random()) - .5);
}

float perlin_fractal(
    vec2 coord,
    int depth,
    float roughness,
    float lacunarity
)
{
    float v = 0.;
    float sum_fac = 0.;

    for (int i = 0; i < depth; i++)
    {
        // Factor (impact of the current layer)
        float fac = 0.;
        roughness = clamp(roughness, -1., 1.);
        if (roughness < 0.)
        {
            // Roughness [-1, 0) will go from fully smooth to normal
            fac = pow(
                lacunarity / max(roughness + 1., .0001),
                float(-i)
            );
        }
        else
        {
            // Roughness [0, 1] will go from normal to fully rough
            fac = pow(
                mix(lacunarity, 1., roughness),
                float(-i)
            );
        }
        sum_fac += fac;

        // Scale of the current layer
        float scale = pow(lacunarity, float(i));

        // Add sample
        v += fac * perlin(coord * scale);

        // Move and rotate the next layer
        coord += 100.;
        coord *= rotate_2d(1.09956);
    }

    return v / sum_fac;
}
